import pandas as pd
from sklearn.linear_model import LinearRegression


def task_func(df, target):
    """
    Perform a linear regression analysis on a DataFrame and return the R-squared score.
    """
    if not isinstance(df, pd.DataFrame):
        raise TypeError("df must be a pandas DataFrame")

    if target not in df.columns:
        raise KeyError(f"Target column '{target}' not found in DataFrame")

    feature_cols = [col for col in df.columns if col != target]
    if not feature_cols:
        raise ValueError("No feature columns available after removing the target column")

    data = df[feature_cols + [target]].dropna()
    if data.empty:
        raise ValueError("No complete rows remaining after dropping missing values")

    if len(data) < 2:
        raise ValueError("At least two complete rows are required to compute an R-squared score")

    y = data[target]
    if not pd.api.types.is_numeric_dtype(y) and not pd.api.types.is_bool_dtype(y):
        y = pd.to_numeric(y, errors="coerce")
        if y.isna().any():
            raise TypeError("Target column must be numeric or convertible to numeric")

    X = data[feature_cols].copy()

    for col in X.columns:
        if pd.api.types.is_datetime64_any_dtype(X[col]):
            X[col] = X[col].astype("int64")

    X = pd.get_dummies(X, drop_first=False)

    if X.shape[1] == 0:
        raise ValueError("No usable feature columns available for regression")

    non_numeric = [col for col in X.columns if not pd.api.types.is_numeric_dtype(X[col])]
    if non_numeric:
        raise TypeError("All feature columns must be numeric or convertible to numeric")

    model = LinearRegression()
    model.fit(X, y)
    score = model.score(X, y)

    return float(score)
